<?php require_once '../config/database.php';require_once '../includes/functions.php';require_admin();$pageTitle='Reviews';$active='reviews';if(isset($_GET['delete'])){$id=(int)$_GET['delete'];$s=$pdo->prepare('DELETE FROM reviews WHERE id=?');$s->execute([$id]);flash('success','Review deleted.');go('reviews.php');}$rows=$pdo->query("SELECT r.*,u.name user_name,u.email,p.name product_name FROM reviews r JOIN users u ON u.id=r.user_id JOIN products p ON p.id=r.product_id ORDER BY r.id DESC")->fetchAll();$flash=flash_get();require 'header.php';?><div class="admin-top"><div><span class="eyebrow">Customer Feedback</span><h1>Reviews</h1><p>Read and manage product reviews.</p></div></div><?php if($flash):?><div class="alert success"><?=e($flash[1])?></div><?php endif;?><section class="admin-card"><div class="table-scroll"><table class="admin-table"><thead><tr><th>ID</th><th>Customer</th><th>Product</th><th>Rating</th><th>Review</th><th>Date</th><th>Action</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td>#<?=$r['id']?></td><td><?=e($r['user_name'])?><br><small><?=e($r['email'])?></small></td><td><?=e($r['product_name'])?></td><td><?=str_repeat('★',(int)$r['rating'])?><?=str_repeat('☆',5-(int)$r['rating'])?></td><td><?=e($r['comment'])?></td><td><?=e($r['created_at'])?></td><td><a class="btn danger-btn" onclick="return confirm('Delete this review?')" href="reviews.php?delete=<?=$r['id']?>">Delete</a></td></tr><?php endforeach;if(!$rows):?><tr><td colspan="7" class="empty-row">No reviews yet.</td></tr><?php endif;?></tbody></table></div></section><?php require 'footer.php';
